{s:QZ,k:'pq',term:'Question 1',lv:'U',n:1,q:"Why does the axial load stop mattering below the ratio e?",say:'Question one. Why does the axial load stop mattering below the ratio [e](/ˈi/)?',cues:{k:'Question one',q:'Why does the'},pause:3.4},
{s:QZ,k:'pa',term:'Answer 1',lv:'U',n:1,q:"Why does the axial load stop mattering below the ratio e?",say:'Below [e](/ˈi/), the thrust is small next to the static capacity, and the load zone hardly changes. So life is set by the radial load alone: Y is zero, and P equals the radial load.',cues:{a1:'Below',a2:'So life is'},al:[["Below e, the thrust is small beside the static capacity: the load zone hardly changes.",'a1'],["Life is set by the radial load alone: Y = 0 and P = Fr.",'a2']],vis:(c,u,b)=>{
 const ax=80,ay=410,aw=480,ah=310,mx=f=>ax+f/3000*aw,my=p=>ay-(p-4000)/3500*ah;
 const pts=MD_range(0,3000,150).map(f=>[mx(f),my(MD_PB(f))]);
 let ce=0;for(let f=0;f<=3000;f+=5){const [e]=MD_eY(f/31500);if(f/5000>e){ce=f;break}}
 const flat=pts.filter(p=>p[0]<mx(ce)),rise=pts.filter(p=>p[0]>=mx(ce));
 let s=MD_T(20,34,'bearing B, Fr = 5 kN, C₀ = 31.5 kN',{fs:22,fw:800,fill:MD_DARK})+MD_arrow(ax,ay,ax+aw+20,ay,MD_DARK,3,12)+MD_arrow(ax,ay,ax,ay-ah-30,MD_DARK,3,12)+
  MD_T(mx(1500),ay+64,'thrust Fa, kN',{fs:22,a:'middle',fill:MD_GREY})+MD_T(ax+10,ay-ah-14,'P, kN',{fs:22,fill:MD_GREY});
 [0,1,2,3].forEach(v=>{s+=MD_L(mx(v*1000),ay,mx(v*1000),ay+8,MD_DARK,2)+MD_T(mx(v*1000),ay+32,String(v),{fs:22,a:'middle',fill:MD_GREY})});
 [5,6,7].forEach(v=>{s+=MD_L(ax-8,my(v*1000),ax,my(v*1000),MD_DARK,2)+MD_T(ax-14,my(v*1000)+8,String(v),{fs:22,a:'end',fill:MD_GREY})});
 const shade=`<rect x="${ax}" y="${ay-ah}" width="${(mx(ce)-ax).toFixed(1)}" height="${ah}" fill="${BLU}" fill-opacity=".12"/>`;
 s+=g('pop',tk(c,'a1'),shade+MD_poly(flat,BLU,6)+MD_T(ax+16,my(5000)-60,'below e:',{fs:22,fw:800,fill:BLU})+MD_T(ax+16,my(5000)-30,'P = Fr',{fs:22,fw:800,fill:BLU}));
 s+=g('pop',tk(c,'a2'),MD_poly(rise,ORG,6)+`<circle cx="${mx(2000)}" cy="${my(MD_PB(2000)).toFixed(1)}" r="9" fill="${ORG}"/>`+MD_T(mx(2000)-14,my(MD_PB(2000))-18,'Fa = 2 kN: 6134 N',{fs:22,fw:800,a:'end',fill:ORG})+MD_T(mx(ce)+14,my(5000)+40,'above e: Y Fa counts',{fs:22,fw:700,fill:ORG}));
 return s}},
{s:QZ,k:'pq',term:'Question 2',lv:'A',n:2,q:"A ball bearing carries Fr = 4 kN and no thrust at n = 900 rev/min, with a required life of 20 000 h. Find Creq.",say:'Question two. A ball bearing carries four kilonewtons radial and no thrust, at nine hundred revolutions a minute, for twenty thousand hours. Find the required rating.',cues:{k:'Question two',q:'A ball bearing'},pause:3.4},
{s:QZ,k:'pa',term:'Answer 2',lv:'A',n:2,q:"A ball bearing carries Fr = 4 kN and no thrust at n = 900 rev/min, with a required life of 20 000 h. Find Creq.",say:'No thrust, so P is just four thousand newtons. The life is one thousand eighty million revolutions. Its cube root is ten point two six, so the bearing needs about forty-one kilonewtons.',cues:{fk:'No thrust',k1:'so P is',k1b:'four thousand newtons',k2:'The life is',k2b:'one thousand eighty',k3:'Its cube root',k3b:'about forty-one'},calc:{f:['P = Fr when Fa = 0','L₁₀ = 60 n L10h / 10⁶','Creq = P × ∛L₁₀'],hint:'A ball bearing: p = 3.',fk:'fk',steps:[["Load",["Fa = 0","P = 4000 N"],["k1","k1b"]],["Life",["60 × 900 × 20 000 / 10⁶","L₁₀ = 1080 million rev"],["k2","k2b"]],["Rating",["4000 × ∛1080 = 4000 × 10.26","Creq = 41 040 N ≈ 41 kN"],["k3","k3b"]]],live:[0,1,2]}},
{s:QZ,k:'pq',term:'Question 3',lv:'N',n:3,q:"A bearing chosen on the dynamic rating fails within weeks, and its races show brinelling. What was missed?",say:'Question three. A bearing chosen on its dynamic rating fails within weeks, and its races show brinelling. What was missed?',cues:{k:'Question three',q:'A bearing chosen'},pause:3.4},
{s:QZ,k:'pa',term:'Answer 3',lv:'N',n:3,q:"A bearing chosen on the dynamic rating fails within weeks, and its races show brinelling. What was missed?",say:'The static check was missed. Slow, stationary or shock loading dents the races even when the dynamic rating is enough, so C zero over P zero must reach the static safety factor. Also suspect the speed limit, misalignment and fits.',cues:{a1:'The static check',a2:'Slow, stationary or',a3:'Also suspect the'},al:[["The static check was missed.",'a1'],["Slow, still or shock loads dent the races even when C ≥ Creq: C₀/P₀ must reach s₀.",'a2'],["Also suspect the limiting speed, misalignment and the fits.",'a3']],vis:(c,u,b)=>{
 const bx=[110,250,390,530];let balls='',dents='';
 bx.forEach(x=>{balls+=`<circle cx="${x}" cy="226" r="44" fill="${MD_STEEL}"/><circle cx="${x-14}" cy="212" r="10" fill="#FFFFFF" fill-opacity=".35"/>`;dents+=`<path d="M${x-22},270 Q${x},292 ${x+22},270 Z" fill="#FFFFFF" stroke="${RED}" stroke-width="3"/>`});
 let s=`<rect x="30" y="270" width="560" height="60" rx="6" fill="${MD_LIGHT}" stroke="${MD_STEEL}" stroke-width="3"/>`+MD_T(310,358,'the race',{fs:22,a:'middle',fill:MD_GREY})+balls;
 s+=g('pop',tk(c,'a1'),MD_T(30,50,'dynamic rating: C ≥ Creq ✓',{fs:24,fw:800,fill:GRN})+MD_T(30,90,'static check: C₀/P₀ not done ✗',{fs:24,fw:800,fill:RED}));
 s+=g('pop',tk(c,'a2'),bx.map(x=>MD_arrow(x,112,x,172,ORG,6,18)).join('')+MD_T(30,150,'shock',{fs:24,fw:800,fill:ORG})+dents+MD_T(310,394,'brinelling: dents pressed into the race',{fs:22,fw:800,a:'middle',fill:RED}));
 const tag=(x,t)=>MD_box(x,420,180,46,{fill:'#F8F9FA',st:PUR,sw:3,r:10})+MD_T(x+90,451,t,{fs:22,fw:800,a:'middle',fill:PUR});
 s+=g('pop',tk(c,'a3'),tag(20,'limiting speed')+tag(220,'misalignment')+tag(420,'fits'));
 return s}},
{s:LS,k:'figs',term:'Your notes',title:'For your notes',say:'Your free notes are the PDF linked in the description. Redraw the selection figure and the gasket joint, then redo all three examples.',cues:{t:'Your free notes',f:'Redraw the selection'},tags:[["Free notes for this lesson (PDF)", "link in the description"], ["The two chapters", "Selection of rolling contact bearings; seals and gaskets"], ["Key terms and glossary", "at the end of the notes"]],figs:[["Selecting the bearing", "5 kN radial and 2 kN thrust at 1200 rev/min for 10 000 h need Creq ≈ 55.0 kN: bearing B (55.3 kN) clears it and passes the static check."], ["The gasket joint and the O-ring", "The pressure case needs 189.9 kN of bolt load against 53.6 kN to seat the gasket; the O-ring is squeezed 21 % and fills 73 % of its groove."]],note:"Sources your free notes draw on: Richard G. Budynas and J. Keith Nisbett (Shigley's Mechanical Engineering Design); V. B. Bhandari (Design of Machine Elements)"},
{s:OUT,k:'outro',term:'Outro',say:'So remember: hours become million revolutions, the larger bolt load wins, and an O-ring needs room. Next time, flexible drives: belt types, materials and construction. See you there!',cues:{f:'So remember',w1:'hours become million',w2:'the larger bolt',w3:'and an O-ring',n:'Next time',s:'See you there'},words:[['HOURS → MILLION REV','BLU','w1'],['LARGER BOLT LOAD WINS','ORG','w2'],['GIVE THE O-RING ROOM','GRN','w3']],next:["NEXT TIME", "Next lesson", "Flexible drives: types, belt materials and construction", "book"],end:'See you there!'}
