function EXTRA(R,ICON){
 /* hook: a motor shaft on its bearings, and a lip seal in section */
 ICON.mdMotor=(x,y)=>`<g transform="translate(${x-190} ${y-85})">${MD_box(0,0,380,170,{fill:'#FFFFFF',st:MD_GREY,sw:3,r:18})}
  <rect x="20" y="40" width="170" height="96" rx="14" fill="${MD_GREY}"/>${[44,66,88,110,132,154,176].map(v=>MD_L(v-10,48,v-10,128,'#7D8794',3)).join('')}
  <rect x="190" y="76" width="168" height="24" rx="4" fill="${MD_STEEL}"/>
  <rect x="226" y="52" width="34" height="24" rx="3" fill="${MD_LIGHT}" stroke="${MD_STEEL}" stroke-width="2"/><circle cx="243" cy="64" r="8" fill="${MD_DARK}"/>
  <rect x="226" y="100" width="34" height="24" rx="3" fill="${MD_LIGHT}" stroke="${MD_STEEL}" stroke-width="2"/><circle cx="243" cy="112" r="8" fill="${MD_DARK}"/>
  ${MD_T(105,98,'motor',{fs:24,fw:800,a:'middle',fill:'#FFFFFF'})}${MD_T(272,40,'bearings',{fs:22,fw:800,fill:BLU})}${MD_T(272,152,'shaft',{fs:22,fill:MD_GREY})}</g>`;
 ICON.mdLip=(x,y)=>`<g transform="translate(${x-190} ${y-85})">${MD_box(0,0,380,170,{fill:'#FFFFFF',st:ORG,sw:3,r:18})}
  <rect x="20" y="18" width="340" height="42" fill="${MD_LIGHT}"/><rect x="20" y="118" width="340" height="32" fill="${MD_STEEL}"/>
  <rect x="20" y="60" width="150" height="58" fill="${MD_OIL}"/>${MD_T(54,98,'oil',{fs:24,fw:800,fill:ORG})}
  <polygon points="170,60 236,60 196,118 180,118" fill="${MD_RUB}"/><circle cx="210" cy="86" r="9" fill="none" stroke="${ORG}" stroke-width="4"/>
  ${MD_T(250,98,'grit, water',{fs:22,fill:MD_GREY})}${MD_T(190,48,'lip seal',{fs:22,fw:800,a:'middle',fill:MD_DARK})}</g>`;
 /* recap pictures: each fills most of its card (about 420 × 330) */
 ICON.mdRecBear=(x,y)=>`<g transform="translate(${x-210} ${y-150})">${MD_brg(120,130,118)}
  ${MD_T(256,96,'C ≥ Creq',{fs:30,fw:800,fill:BLU})}${MD_T(256,140,'55.3 ≥ 55.0',{fs:24,fw:700,fill:MD_DARK})}${MD_T(256,184,'s₀ = 6.3',{fs:24,fw:700,fill:MD_DARK})}
  ${MD_T(210,296,'bearing B passes',{fs:26,fw:800,a:'middle',fill:BLU})}</g>`;
 ICON.mdRecGasket=(x,y)=>`<g transform="translate(${x-210} ${y-150})">${MD_joint(40,46)}
  ${MD_T(0,222,MD_sub('W','m2'),{fs:24,fw:800,fill:MD_GREY})}${MD_bar(64,200,53.6,1.8,30,MD_GREY,.6)}${MD_T(64+53.6*1.8+10,224,'53.6 kN',{fs:22,fw:700,fill:MD_GREY})}
  ${MD_T(0,276,MD_sub('W','m1'),{fs:24,fw:800,fill:ORG})}${MD_bar(64,254,189.9,1.8,30,ORG)}${MD_T(64+189.9*1.8-10,277,'189.9 kN',{fs:22,fw:800,a:'end',fill:'#FFFFFF'})}</g>`;
 ICON.mdRecOring=(x,y)=>{const k=46,d=3.53*k,gw=4.80*k,gh=2.80*k,gx=100,gy=70,ry=gh/2,rx=(d/2)*(d/2)/ry;
  return `<g transform="translate(${x-210} ${y-150})"><rect x="20" y="${gy}" width="380" height="${(gh+40).toFixed(1)}" fill="${MD_LIGHT}" stroke="${MD_STEEL}" stroke-width="2"/>
  <rect x="${gx}" y="${gy}" width="${gw.toFixed(1)}" height="${gh.toFixed(1)}" fill="#FFFFFF" stroke="${MD_STEEL}" stroke-width="2"/><rect x="20" y="${gy-20}" width="380" height="20" fill="${MD_STEEL}"/>
  <circle cx="${(gx+gw/2).toFixed(1)}" cy="${(gy+ry).toFixed(1)}" r="${(d/2).toFixed(1)}" fill="none" stroke="${GRN}" stroke-width="3" stroke-dasharray="8 6"/>
  <ellipse cx="${(gx+gw/2).toFixed(1)}" cy="${(gy+ry).toFixed(1)}" rx="${rx.toFixed(1)}" ry="${ry.toFixed(1)}" fill="${GRN}" fill-opacity=".8"/>
  ${MD_T(210,300,'squeeze 21 % · fill 73 %',{fs:26,fw:800,a:'middle',fill:GRN})}</g>`};
}
